impl<const U: SIUnit, const B: Base> From<SIQuantity<U, f32, B>> for f32
where
    Check<{ U.is_plain_number() }>: True,
{
    fn from(q: SIQuantity<U, f32, B>) -> f32 {
        q.0 * const { <f32 as From<Exact>>::from(U.size()) }
    }
}

