/// The coherent units printed by name, not as their product of base units.
static NAMED: [(SIUnit, &str); 16] = [
    (
        METRE
            .unit()
            .times(KILOGRAM.unit(), 1)
            .times(SECOND.unit(), -2),
        "N",
    ),
    (
        SIUnit::ONE
            .times(METRE.unit(), 2)
            .times(KILOGRAM.unit(), 1)
            .times(SECOND.unit(), -2),
        "J",
    ),
    (
        SIUnit::ONE
            .times(METRE.unit(), 2)
            .times(KILOGRAM.unit(), 1)
            .times(SECOND.unit(), -3),
        "W",
    ),
    (
        SIUnit::ONE
            .times(METRE.unit(), -1)
            .times(KILOGRAM.unit(), 1)
            .times(SECOND.unit(), -2),
        "Pa",
    ),
    (SIUnit::ONE.times(SECOND.unit(), -1), "Hz"),
    (SECOND.unit().times(AMPERE.unit(), 1), "C"),
    (
        SIUnit::ONE
            .times(METRE.unit(), 2)
            .times(KILOGRAM.unit(), 1)
            .times(SECOND.unit(), -3)
            .times(AMPERE.unit(), -1),
        "V",
    ),
    (
        SIUnit::ONE
            .times(METRE.unit(), -2)
            .times(KILOGRAM.unit(), -1)
            .times(SECOND.unit(), 4)
            .times(AMPERE.unit(), 2),
        "F",
    ),
    (
        SIUnit::ONE
            .times(METRE.unit(), 2)
            .times(KILOGRAM.unit(), 1)
            .times(SECOND.unit(), -3)
            .times(AMPERE.unit(), -2),
        "Ω",
    ),
    (
        SIUnit::ONE
            .times(METRE.unit(), -2)
            .times(KILOGRAM.unit(), -1)
            .times(SECOND.unit(), 3)
            .times(AMPERE.unit(), 2),
        "S",
    ),
    (
        SIUnit::ONE
            .times(METRE.unit(), 2)
            .times(KILOGRAM.unit(), 1)
            .times(SECOND.unit(), -2)
            .times(AMPERE.unit(), -1),
        "Wb",
    ),
    (
        KILOGRAM
            .unit()
            .times(SECOND.unit(), -2)
            .times(AMPERE.unit(), -1),
        "T",
    ),
    (
        SIUnit::ONE
            .times(METRE.unit(), 2)
            .times(KILOGRAM.unit(), 1)
            .times(SECOND.unit(), -2)
            .times(AMPERE.unit(), -2),
        "H",
    ),
    (SIUnit::ONE.times(RADIAN.unit(), 2), "sr"),
    (
        SIUnit::ONE
            .times(METRE.unit(), -2)
            .times(CANDELA.unit(), 1)
            .times(RADIAN.unit(), 2),
        "lx",
    ),
    (
        SIUnit::ONE.times(SECOND.unit(), -1).times(MOLE.unit(), 1),
        "kat",
    ),
];

/// The prefix yotta (`Y`): 10^24.
pub const YOTTA: SIQuantity<
    { SIUnit::prefix("Y", Exact::int(1000000000000000000000000)) },
    Exact,
    NOT_BASE,
> = SIQuantity::ONE;
/// The prefix zetta (`Z`): 10^21.
pub const ZETTA: SIQuantity<
    { SIUnit::prefix("Z", Exact::int(1000000000000000000000)) },
    Exact,
    NOT_BASE,
> = SIQuantity::ONE;
/// The prefix exa (`E`): 10^18.
pub const EXA: SIQuantity<
    { SIUnit::prefix("E", Exact::int(1000000000000000000)) },
    Exact,
    NOT_BASE,
> = SIQuantity::ONE;
